import Component from 'flarum/common/Component';
import app from 'flarum/forum/app';
/**
 * SectionHeader — the "Recent Discussions" title + count badge that sits above
 * the IndexPage toolbar/filter row.
 *
 * The count tries a forum attribute first (now backed server-side by
 * mosaicDiscussionCount), then the loaded-store size, else hides.
 */
export default class SectionHeader extends Component {
  view() {
    const count = this.attrs.count ?? resolveCount();
    return m("div", {
      className: "MosaicSectionHead"
    }, m("h2", {
      className: "MosaicSectionHead-title"
    }, this.attrs.title || 'Recent Discussions'), count != null && m("span", {
      className: "MosaicSectionHead-count"
    }, format(count)));
  }
}
function resolveCount() {
  const f = app.forum;
  const fromAttr = f.attribute('discussionCount') ?? f.attribute('discussionsCount') ?? f.attribute('mosaicDiscussionCount');
  if (fromAttr != null) {
    const n = Number(fromAttr);
    if (Number.isFinite(n)) return n;
  }
  try {
    const arr = app.store.all('discussions');
    return Array.isArray(arr) ? arr.length : null;
  } catch (e) {
    return null;
  }
}
function format(n) {
  const v = Number(n) || 0;
  if (v >= 1000) return (v / 1000).toFixed(1).replace(/\.0$/, '') + 'k';
  return v.toLocaleString();
}
flarum.reg.add('ernestdefoe-mosaic', 'forum/components/SectionHeader', SectionHeader);